SELECT c.relrowsecurity AS rls_enabled, (SELECT count(*) FROM public.tm_journey_goal_drafts) AS drafts, (SELECT count(*) FROM public.tm_memberships) AS memberships, (SELECT count(*) FROM public.tm_patients) AS patients, (SELECT count(*) FROM public.tm_membership_grants) AS clinical_grants, has_table_privilege('anon','public.tm_journey_goal_drafts','SELECT') AS anon_read, has_table_privilege('authenticated','public.tm_journey_goal_drafts','SELECT') AS auth_read, has_table_privilege('authenticated','public.tm_journey_goal_drafts','INSERT') AS direct_insert, has_table_privilege('authenticated','public.tm_journey_goal_drafts','UPDATE') AS direct_update, has_table_privilege('authenticated','public.tm_journey_goal_drafts','DELETE') AS direct_delete, p.prosecdef AS security_definer, p.proconfig::text AS function_config, has_function_privilege('anon',p.oid,'EXECUTE') AS anon_execute, has_function_privilege('authenticated',p.oid,'EXECUTE') AS auth_execute, md5(regexp_replace(p.prosrc,'[[:space:]]','','g'))='ee31a2f9cab1f9096b66f7db0a3d8f96' AS source_matches, (SELECT count(*) FROM pg_policies WHERE schemaname='public' AND tablename='tm_journey_goal_drafts' AND policyname='tm_journey_goal_draft_read' AND cmd='SELECT') AS read_policies FROM pg_class c JOIN pg_proc p ON p.oid='public.tm_create_journey_goal_draft(uuid,uuid,uuid,text,text)'::regprocedure WHERE c.oid='public.tm_journey_goal_drafts'::regclass;